export function validateFleetPlanRunLimits(value: unknown, path: string, contract: string): void {
  if (!isRecord(value)) fail(contract, path, "expected object");
  const record = value as JsonRecord;
  if (!Object.hasOwn(record, "deadline_at")) fail(contract, `${path}.deadline_at`, "missing required property");
  if (!Object.hasOwn(record, "step_timeout_seconds")) fail(contract, `${path}.step_timeout_seconds`, "missing required property");
  for (const [key, item] of Object.entries(record)) {
    switch (key) {
        case "deadline_at": {
          if (typeof item !== "string") fail(contract, `${path}.deadline_at`, "expected string");
          if (Number.isNaN(Date.parse(item as string))) fail(contract, `${path}.deadline_at`, "expected date-time string");
          break;
        }
        case "step_timeout_seconds": {
          if (typeof item !== "number" || !Number.isFinite(item)) fail(contract, `${path}.step_timeout_seconds`, "expected finite number");
          if ((item as number) > 21600.0) fail(contract, `${path}.step_timeout_seconds`, "must be <= 21600.0");
          break;
        }
      default: {
        fail(contract, `${path}.${key}`, "unexpected property");
      }
    }
  }
}

export function validateFleetPlanRuntimeToolTrustReceipt(value: unknown, path: string, contract: string): void {
  if (!isRecord(value)) fail(contract, path, "expected object");
  const record = value as JsonRecord;
  if (!Object.hasOwn(record, "name")) fail(contract, `${path}.name`, "missing required property");
  if (!Object.hasOwn(record, "sha256")) fail(contract, `${path}.sha256`, "missing required property");
  if (!Object.hasOwn(record, "byte_count")) fail(contract, `${path}.byte_count`, "missing required property");
  if (!Object.hasOwn(record, "authority_id")) fail(contract, `${path}.authority_id`, "missing required property");
  for (const [key, item] of Object.entries(record)) {
    switch (key) {
        case "authority_id": {
          if (typeof item !== "string") fail(contract, `${path}.authority_id`, "expected string");
          if ((item as string).length < 1) fail(contract, `${path}.authority_id`, "must contain at least 1 characters");
          break;
        }
        case "byte_count": {
          if (typeof item !== "number" || !Number.isFinite(item)) fail(contract, `${path}.byte_count`, "expected finite number");
          if (!Number.isInteger(item)) fail(contract, `${path}.byte_count`, "expected integer");
          if ((item as number) < 0.0) fail(contract, `${path}.byte_count`, "must be >= 0.0");
          break;
        }
        case "name": {
          if (typeof item !== "string") fail(contract, `${path}.name`, "expected string");
          if ((item as string).length < 1) fail(contract, `${path}.name`, "must contain at least 1 characters");
          if ((item as string).length > 240) fail(contract, `${path}.name`, "must contain at most 240 characters");
          break;
        }
        case "origin": {
          if (item !== "host") fail(contract, `${path}.origin`, "did not match required constant");
          if (typeof item !== "string") fail(contract, `${path}.origin`, "expected string");
          break;
        }
        case "sha256": {
          if (typeof item !== "string") fail(contract, `${path}.sha256`, "expected string");
          break;
        }
      default: {
        fail(contract, `${path}.${key}`, "unexpected property");
      }
    }
  }
}

export function validateFleetPlanRuntimeTrustReceipt(value: unknown, path: string, contract: string, refStack: Set<string>): void {
  if (!isRecord(value)) fail(contract, path, "expected object");
  const record = value as JsonRecord;
  if (!Object.hasOwn(record, "backend_id")) fail(contract, `${path}.backend_id`, "missing required property");
  if (!Object.hasOwn(record, "host_toolchain_id")) fail(contract, `${path}.host_toolchain_id`, "missing required property");
  if (!Object.hasOwn(record, "configuration_id")) fail(contract, `${path}.configuration_id`, "missing required property");
  if (!Object.hasOwn(record, "kernel_boundary")) fail(contract, `${path}.kernel_boundary`, "missing required property");
  if (!Object.hasOwn(record, "remote_execution")) fail(contract, `${path}.remote_execution`, "missing required property");
  if (!Object.hasOwn(record, "experimental")) fail(contract, `${path}.experimental`, "missing required property");
  if (!Object.hasOwn(record, "hostname_resolution_count")) fail(contract, `${path}.hostname_resolution_count`, "missing required property");
  for (const [key, item] of Object.entries(record)) {
    switch (key) {
        case "backend_id": {
          if (typeof item !== "string") fail(contract, `${path}.backend_id`, "expected string");
          if ((item as string).length < 1) fail(contract, `${path}.backend_id`, "must contain at least 1 characters");
          if ((item as string).length > 80) fail(contract, `${path}.backend_id`, "must contain at most 80 characters");
          break;
        }
        case "configuration_id": {
          if (typeof item !== "string") fail(contract, `${path}.configuration_id`, "expected string");
          if ((item as string).length < 1) fail(contract, `${path}.configuration_id`, "must contain at least 1 characters");
          break;
        }
        case "experimental": {
          if (typeof item !== "boolean") fail(contract, `${path}.experimental`, "expected boolean");
          break;
        }
        case "host_environment_names": {
          if (!Array.isArray(item)) fail(contract, `${path}.host_environment_names`, "expected array");
          (item as unknown[]).forEach((item, index) => {
            if (typeof item !== "string") fail(contract, `${`${path}.host_environment_names`}[${index}]`, "expected string");
          });
          break;
        }
        case "host_toolchain_id": {
          if (typeof item !== "string") fail(contract, `${path}.host_toolchain_id`, "expected string");
          if ((item as string).length < 1) fail(contract, `${path}.host_toolchain_id`, "must contain at least 1 characters");
          break;
        }
        case "host_tools": {
          if (!Array.isArray(item)) fail(contract, `${path}.host_tools`, "expected array");
          (item as unknown[]).forEach((item, index) => {
            validateReference("FleetPlanRuntimeToolTrustReceipt", validateFleetPlanRuntimeToolTrustReceipt, item, `${`${path}.host_tools`}[${index}]`, contract, refStack);
          });
          break;
        }
        case "hostname_resolution_count": {
          if (typeof item !== "number" || !Number.isFinite(item)) fail(contract, `${path}.hostname_resolution_count`, "expected finite number");
          if (!Number.isInteger(item)) fail(contract, `${path}.hostname_resolution_count`, "expected integer");
          if ((item as number) < 0.0) fail(contract, `${path}.hostname_resolution_count`, "must be >= 0.0");
          break;
        }
        case "kernel_boundary": {
          if (!(["shared_host_kernel", "application_kernel", "virtual_machine"] as unknown[]).includes(item)) fail(contract, `${path}.kernel_boundary`, "was not an allowed enum value");
          if (typeof item !== "string") fail(contract, `${path}.kernel_boundary`, "expected string");
          break;
        }
        case "remote_execution": {
          if (typeof item !== "boolean") fail(contract, `${path}.remote_execution`, "expected boolean");
          break;
        }
      default: {
        fail(contract, `${path}.${key}`, "unexpected property");
      }
    }
  }
}
